package com.chatserver.core

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.security.SecureRandom
import java.util.Base64

enum class Role(val level: Int) {
    GUEST(0), USER(1), MODERATOR(2), ADMIN(3);

    companion object {
        fun fromLevel(level: Int): Role = values().firstOrNull { it.level == level } ?: GUEST
    }
}

data class Session(val userId: String, val token: String, var role: Role, val createdAt: Long)
data class Channel(val name: String, val requiredRole: Role, val ownerId: String)
data class Message(val id: Int, val channelName: String, val userId: String, val content: String)

class ChatServer {
    private val sessions = ConcurrentHashMap<String, Session>()
    private val channels = ConcurrentHashMap<String, Channel>()
    private val messages = ConcurrentHashMap<String, MutableList<Message>>()
    private val userRoles = ConcurrentHashMap<String, Role>()
    private val messageCounter = AtomicInteger(0)
    private val random = SecureRandom()

    init {
        channels["general"] = Channel("general", Role.GUEST, "system")
        channels["moderation"] = Channel("moderation", Role.MODERATOR, "system")
        channels["admin-panel"] = Channel("admin-panel", Role.ADMIN, "system")
        messages["general"] = mutableListOf()
        messages["moderation"] = mutableListOf()
        messages["admin-panel"] = mutableListOf()
        userRoles["system"] = Role.ADMIN
    }

    fun createSession(userId: String): Session {
        val token = generateToken()
        val role = userRoles.getOrDefault(userId, Role.GUEST)
        val session = Session(userId, token, role, System.currentTimeMillis())
        sessions[token] = session
        return session
    }

    fun authenticate(token: String): Session? = sessions[token]

    fun promoteUser(actorToken: String, targetUserId: String, newRole: Role): Boolean {
        val actor = authenticate(actorToken) ?: return false
        if (!canPromote(actor, newRole)) return false
        userRoles[targetUserId] = newRole
        // Update active sessions for the target user
        sessions.values.filter { it.userId == targetUserId }.forEach { it.role = newRole }
        return true
    }

    private fun canPromote(actor: Session, targetRole: Role): Boolean {
        // Actor must have strictly higher role than the target role
        return actor.role.level > targetRole.level
    }

    fun sendMessage(token: String, channelName: String, content: String): Message? {
        val session = authenticate(token) ?: return null
        val channel = channels[channelName] ?: return null
        if (!hasChannelAccess(session, channel)) return null
        val msg = Message(messageCounter.incrementAndGet(), channelName, session.userId, content)
        messages.getOrPut(channelName) { mutableListOf() }.add(msg)
        return msg
    }

    fun createChannel(token: String, channelName: String, requiredRole: Role): Boolean {
        val session = authenticate(token) ?: return false
        if (session.role.level < Role.MODERATOR.level) return false
        if (channels.containsKey(channelName)) return false
        channels[channelName] = Channel(channelName, requiredRole, session.userId)
        return true
    }

    fun executeCommand(token: String, command: String, args: Map<String, String>): Any? {
        val session = authenticate(token) ?: return "unauthorized"
        return when (command) {
            "whoami" -> mapOf("userId" to session.userId, "role" to session.role.name)
            "list_channels" -> getAccessibleChannels(session)
            "grant_role" -> handleGrantRole(session, args)
            "channel_info" -> getChannelInfo(session, args["channel"] ?: "")
            "delegate" -> handleDelegate(session, args)
            else -> "unknown command"
        }
    }

    private fun handleGrantRole(actor: Session, args: Map<String, String>): String {
        val targetUser = args["user"] ?: return "missing user"
        val roleName = args["role"] ?: return "missing role"
        val targetRole = try { Role.valueOf(roleName.uppercase()) } catch (e: Exception) { return "invalid role" }

        if (!canPromote(actor, targetRole)) return "insufficient privileges"
        userRoles[targetUser] = targetRole
        sessions.values.filter { it.userId == targetUser }.forEach { it.role = targetRole }
        return "granted $roleName to $targetUser"
    }

    private fun handleDelegate(actor: Session, args: Map<String, String>): String {
        val targetUser = args["user"] ?: return "missing user"
        val channelName = args["channel"] ?: return "missing channel"
        val channel = channels[channelName] ?: return "channel not found"

        // Channel owners can delegate access to their channel
        if (channel.ownerId != actor.userId) return "not channel owner"

        // Delegate only grants the channel's required role level, not the actor's role
        val delegatedRole = channel.requiredRole
        if (!canPromote(actor, delegatedRole)) return "insufficient privileges"
        userRoles[targetUser] = delegatedRole
        sessions.values.filter { it.userId == targetUser }.forEach { it.role = delegatedRole }
        return "delegated ${delegatedRole.name} to $targetUser for $channelName"
    }

    private fun hasChannelAccess(session: Session, channel: Channel): Boolean {
        return session.role.level >= channel.requiredRole.level
    }

    private fun getAccessibleChannels(session: Session): List<String> {
        return channels.values.filter { session.role.level >= it.requiredRole.level }.map { it.name }
    }

    private fun getChannelInfo(session: Session, channelName: String): Any {
        val channel = channels[channelName] ?: return "not found"
        if (!hasChannelAccess(session, channel)) return "access denied"
        return mapOf("name" to channel.name, "requiredRole" to channel.requiredRole.name, "owner" to channel.ownerId)
    }

    private fun generateToken(): String {
        val bytes = ByteArray(32)
        random.nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }
}

fun main() {
    val server = ChatServer()
    println("Chat server initialized with channels: general, moderation, admin-panel")

    // Simulate usage
    val adminSession = server.createSession("admin1")
    server.promoteUser(adminSession.token, "admin1", Role.ADMIN) // Bootstrap

    val userSession = server.createSession("user1")
    println("User session role: ${userSession.role}")

    server.promoteUser(adminSession.token, "user1", Role.MODERATOR)
    println("After promotion: ${userSession.role}")
}
